#!/usr/bin/env bash
# Claims probe — generated by /code-review v2.
#
# Every fact re-derives itself. Two fields govern how a result is read:
#   state:     OPEN  = defect still stands   | FIXED = defect was fixed
#   direction: exact | at-most | at-least    (which way is improvement)
#
#   HOLDS + FIXED -> closed, skipped next run
#   HOLDS + OPEN  -> STILL-OPEN, carried into every report, never skipped
#   DRIFT + FIXED -> regression, loud
#   DRIFT + OPEN  -> improvement or change, re-measure
#
# Usage: bash docs/reviews/claims-2026-10-06.probe.sh
# Exit:  0 = nothing regressed, 1 = a FIXED claim broke or a shape check failed

cd "$(dirname "$0")/../.." || exit 2

pass=0; still_open=0; regressed=0; drift=0
REPORT="docs/reviews/claims-2026-10-06.md"

# ---------------------------------------------------------------- self-check
if [ -f "$REPORT" ]; then
  lines=$(grep -cve '^[[:space:]]*$' "$REPORT")
  grades=$(grep -cE '^\| [A-F][+-]? ' "$REPORT" || true)
  [ "$lines" -le 60 ] || { echo "SHAPE FAIL: report is $lines non-blank lines (max 60)"; exit 1; }
  [ "$grades" -eq 0 ] || { echo "SHAPE FAIL: report contains $grades letter-grade rows"; exit 1; }
  printf '  shape: %s non-blank lines, %s grade rows\n\n' "$lines" "$grades"
fi

# ------------------------------------------------------------------- checker
check() {
  local id="$1" state="$2" dir="$3" expected="$4" actual="$5" desc="$6"
  local ok=1
  case "$dir" in
    exact)    [ "$actual" = "$expected" ] || ok=0 ;;
    at-most)  [ "$actual" -le "$expected" ] 2>/dev/null || ok=0 ;;
    at-least) [ "$actual" -ge "$expected" ] 2>/dev/null || ok=0 ;;
  esac
  if [ "$ok" = 1 ] && [ "$state" = "FIXED" ]; then
    printf '  \033[32mHOLDS     \033[0m %-5s %s (= %s)\n' "$id" "$desc" "$actual"; pass=$((pass+1))
  elif [ "$ok" = 1 ] && [ "$state" = "OPEN" ]; then
    printf '  \033[33mSTILL-OPEN\033[0m %-5s %s (= %s)\n' "$id" "$desc" "$actual"; still_open=$((still_open+1))
  elif [ "$state" = "FIXED" ]; then
    printf '  \033[31mREGRESSED \033[0m %-5s %s expected %s %s, got %s\n' "$id" "$desc" "$dir" "$expected" "$actual"; regressed=$((regressed+1))
  else
    printf '  \033[36mCHANGED   \033[0m %-5s %s was %s %s, now %s — re-measure\n' "$id" "$desc" "$dir" "$expected" "$actual"; drift=$((drift+1))
  fi
}
# count of lines, whitespace-stripped, never failing the pipeline
n() { wc -l | tr -d ' '; }
c() { grep -c "$@" 2>/dev/null | tr -d ' '; }

